13	public class AtomicJsonFileStore<T> {
14	
15	    private static final Logger log = LoggerFactory.getLogger(AtomicJsonFileStore.class);
16	
17	    private final Path target;
18	    private final JavaType type;
19	    private final ObjectMapper mapper;
20	
21	    public AtomicJsonFileStore(Path target, JavaType type, ObjectMapper mapper) {
22	        this.target = target;
23	        this.type = type;
24	        this.mapper = mapper;
25	    }
26	
27	    public T load(T defaultValue) {
28	        if (!Files.exists(target)) {
29	            return defaultValue;
30	        }
31	        try {
32	            return mapper.readValue(target.toFile(), type);
33	        } catch (IOException e) {
34	            log.warn("Failed to read store file {}, falling back to default", target.getFileName(), e);
35	            return defaultValue;
36	        }
37	    }
38	
39	    public void save(T value) {
40	        try {
41	            Path parent = target.toAbsolutePath().getParent();
42	            if (parent != null) {
43	                Files.createDirectories(parent);
44	            }
45	            Path tempFile = Files.createTempFile(parent, "atomic-json-", ".tmp");
46	            try {
47	                mapper.writeValue(tempFile.toFile(), value);
48	                Files.move(tempFile, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
49	            } finally {
50	                Files.deleteIfExists(tempFile);
51	            }
52	        } catch (IOException e) {
53	            throw new StoreIOException("Failed to save store file: " + target.getFileName(), e);
54	        }
55	    }
56	}
