package ru.assistant.tools;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.IOException;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class AddReminderToolTest {

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    @Test
    public void executeAddsReminderAndReturnsConfirmationText() throws IOException, ToolError {
        ReminderStore store = new ReminderStore(reminderFile());
        AddReminderTool tool = new AddReminderTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("text", "buy milk");
        args.put("dueIso", "2026-08-14T09:00:00Z");

        String result = tool.execute(args);

        assertTrue(result.contains("buy milk"));
        assertTrue(result.contains("2026-08-14T09:00:00Z"));
        List<ReminderStore.ReminderEntry> stored = store.find(null);
        assertEquals(1, stored.size());
        assertEquals("buy milk", stored.get(0).getText());
    }

    @Test
    public void executeAcceptsOffsetDateTimeFormat() throws IOException, ToolError {
        ReminderStore store = new ReminderStore(reminderFile());
        AddReminderTool tool = new AddReminderTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("text", "buy milk");
        args.put("dueIso", "2026-08-14T09:00:00+03:00");

        String result = tool.execute(args);

        assertTrue(result.contains("2026-08-14T09:00:00+03:00"));
    }

    @Test
    public void executeThrowsToolErrorWhenTextMissing() throws IOException {
        ReminderStore store = new ReminderStore(reminderFile());
        AddReminderTool tool = new AddReminderTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("dueIso", "2026-08-14T09:00:00Z");

        try {
            tool.execute(args);
            fail("Expected ToolError");
        } catch (ToolError e) {
            assertEquals("text is required", e.getMessage());
        }
    }

    @Test
    public void executeThrowsToolErrorWhenTextIsBlank() throws IOException {
        ReminderStore store = new ReminderStore(reminderFile());
        AddReminderTool tool = new AddReminderTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("text", "   ");
        args.put("dueIso", "2026-08-14T09:00:00Z");

        try {
            tool.execute(args);
            fail("Expected ToolError");
        } catch (ToolError e) {
            assertEquals("text is required", e.getMessage());
        }
    }

    @Test
    public void executeThrowsToolErrorForInvalidDueIso() throws IOException {
        ReminderStore store = new ReminderStore(reminderFile());
        AddReminderTool tool = new AddReminderTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("text", "buy milk");
        args.put("dueIso", "not-a-date");

        try {
            tool.execute(args);
            fail("Expected ToolError");
        } catch (ToolError e) {
            assertFalse(e.getMessage().toLowerCase().contains("exception"));
            assertFalse(e.getMessage().contains("\tat "));
