    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    @Test
    public void executeReturnsMatchingEntriesForSubstring() throws IOException, ToolError {
        ReminderStore store = new ReminderStore(reminderFile());
        store.add("Buy Milk", "2026-08-14T09:00:00Z");
        store.add("Call mom", "2026-08-15T09:00:00Z");
        FindItemsTool tool = new FindItemsTool(store);
        Map<String, Object> args = new HashMap<>();
        args.put("query", "milk");

        String result = tool.execute(args);

        assertTrue(result.contains("Buy Milk"));
        assertTrue(result.contains("2026-08-14T09:00:00Z"));
        assertFalse(result.contains("Call mom"));
    }

