    public void executeReturnsNoReminderFoundMessageWhenEmpty() throws IOException, ToolError {
        ReminderStore store = new ReminderStore(reminderFile());
        FindItemsTool tool = new FindItemsTool(store);

        String result = tool.execute(Collections.<String, Object>emptyMap());

        assertEquals("No reminders found.", result);
    }

